# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ABDESTİN FARZLARI (4 FARZ) VE SÜNNETLERİ (MAİDE SURESİ, 6. AYET)</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Abdestin 4 Farzı (Olmazsa Olmaz)</text>\n  <text x="180" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">1. Yüzü Yıkamak (Saç bitiminden çene altına)</text>\n  <text x="180" y="132" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">2. Elleri ve Kolları Dirseklerle Beraber Yıkamak</text>\n  <text x="180" y="162" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">3. Başın Dörtte Birini Mesh Etmek (Islak elle)</text>\n  <text x="180" y="192" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">4. Ayakları Topuklarla Beraber Yıkamak</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" fill="#475569">Biri eksik kalırsa abdest geçerli olmaz.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Abdestin Başlıca Sünnetleri ve Âdâbı</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• Niyet etmek ve Eûzü-Besmele çekmek</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11.5" fill="#14532d">• Elleri bileklere kadar yıkamak, diş temizliği</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11.5" fill="#14532d">• Ağza ve burna üçer kez su vermek</text>\n  <text x="520" y="158" text-anchor="middle" font-size="11.5" fill="#14532d">• Kulakları ve boynu mesh etmek</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11.5" fill="#14532d">• Organları sırayla, sağdan başlayıp üçer kez</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">yıkamak ve suyu asla israf etmemek!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GUSÜL (BOY ABDESTİ) VE TEYEMMÜMÜN FARZLARI</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Gusül (Boy Abdesti) ve 3 Farzı</text>\n  <text x="180" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">1. Ağza bolca su alıp boğaza kadar çalkalamak</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#334155">(Mazmaza)</text>\n  <text x="180" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">2. Burna genze kadar su çekip temizlemek</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11" fill="#334155">(İstinşak)</text>\n  <text x="180" y="190" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">3. Bütün vücudu kuru yer kalmadan yıkamak</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#0f172a">İğne ucu kadar kuru yer kalmamalıdır.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Teyemmüm (Toprakla Temizlik) ve 2 Farzı</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11" fill="#713f12">Su bulunmadığında veya suyu kullanmak sağlığa</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#713f12">zararlı olduğunda temiz toprak cinsiyle alınır.</text>\n  <text x="520" y="142" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">1. Teyemmüm için NİYET ETMEK</text>\n  <text x="520" y="170" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">2. Elleri temiz toprağa sürüp YÜZÜ ve</text>\n  <text x="520" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">KOLLARI (dirseklerle beraber) MESH ETMEK</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" fill="#475569">Su bulunduğu anda teyemmüm bozulur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ABDESTİ BOZAN DURUMLAR VE HÜKΜÎ TEMİZLİK TABLOSU</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Abdesti Bozan Başlıca Durumlar</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#7f1d1d">• Tuvalet ihtiyacını gidermek ve yel çıkması</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11.5" fill="#7f1d1d">• Vücudun herhangi bir yerinden kan, irin akması</text>\n  <text x="180" y="142" text-anchor="middle" font-size="11.5" fill="#7f1d1d">• Ağız dolusu kusmak</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11.5" fill="#7f1d1d">• Uyuyakalmak, bayılmak veya sarhoş olmak</text>\n  <text x="180" y="186" text-anchor="middle" font-size="11.5" fill="#7f1d1d">• Namaz kılarken yanındakinin duyacağı</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b91c1c">şekilde sesli gülmek (kahkaha atmak)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Abdestsiz Yapılamayan İbadetler</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">1. Namaz Kılmak (Farz, vacip veya nafile)</text>\n  <text x="520" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">2. Kâbe\'yi Tavaf Etmek</text>\n  <text x="520" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">3. Kur\'an-ı Kerim Mushafına El Sürmek</text>\n  <text x="520" y="186" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">4. Tilavet, Sehiv ve Şükür Secdesi Yapmak</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" fill="#475569">«Temizlik imanın yarısıdır.» (Hadis-i Şerif)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
